CREATE VIEW mart_playability_v1 AS WITH rule_weights AS (SELECT max(CASE  WHEN ((RuleValue = 'Tank Controls')) THEN (RuleWeight) ELSE NULL END) AS control_penalty, max(CASE  WHEN ((RuleValue = 'SHMUP')) THEN (RuleWeight) ELSE NULL END) AS shmup_penalty, max(CASE  WHEN ((RuleValue = 'Souls-like')) THEN (RuleWeight) ELSE NULL END) AS soulslike_penalty, max(CASE  WHEN ((RuleValue = 'Difficulty Mitigation')) THEN (RuleWeight) ELSE NULL END) AS mitigation_bonus FROM PreferenceRule)SELECT dg.GameKey, dg.GameID, dg.GameTitle, COALESCE(gpp.SpecialAccessoryRequired, CAST('f' AS BOOLEAN)) AS SpecialAccessoryRequired, COALESCE(gpp.ControlSchemeRisk, 'Unknown') AS ControlSchemeRisk, COALESCE(gpp.RhythmFlag, CAST('f' AS BOOLEAN)) AS RhythmFlag, COALESCE(gpp.SHMUPFlag, CAST('f' AS BOOLEAN)) AS SHMUPFlag, COALESCE(gpp.SoulslikeFlag, CAST('f' AS BOOLEAN)) AS SoulslikeFlag, COALESCE(gpp.MitigationAvailable, CAST('f' AS BOOLEAN)) AS MitigationAvailable, gpp.PlayabilityNotes, CASE  WHEN ((gpp.SpecialAccessoryRequired = CAST('t' AS BOOLEAN))) THEN (CAST('t' AS BOOLEAN)) WHEN ((gpp.RhythmFlag = CAST('t' AS BOOLEAN))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS hard_exclusion_flag, CASE  WHEN ((gpp.SpecialAccessoryRequired = CAST('t' AS BOOLEAN))) THEN ('Special accessory required') WHEN ((gpp.RhythmFlag = CAST('t' AS BOOLEAN))) THEN ('Rhythm-focused gameplay') ELSE NULL END AS exclusion_reason, (((CASE  WHEN ((gpp.ControlSchemeRisk = 'High')) THEN (rw.control_penalty) ELSE 0 END + CASE  WHEN ((gpp.SHMUPFlag = CAST('t' AS BOOLEAN))) THEN (rw.shmup_penalty) ELSE 0 END) + CASE  WHEN ((gpp.SoulslikeFlag = CAST('t' AS BOOLEAN))) THEN (rw.soulslike_penalty) ELSE 0 END) + CASE  WHEN (((gpp.MitigationAvailable = CAST('t' AS BOOLEAN)) AND ((gpp.SoulslikeFlag = CAST('t' AS BOOLEAN)) OR (gpp.SHMUPFlag = CAST('t' AS BOOLEAN)) OR (gpp.ControlSchemeRisk IN ('Moderate', 'High'))))) THEN (rw.mitigation_bonus) ELSE 0 END) AS playability_adjustment, CASE  WHEN ((gpp.GameID IS NULL)) THEN ('Unknown') WHEN (((gpp.SpecialAccessoryRequired = CAST('t' AS BOOLEAN)) OR (gpp.RhythmFlag = CAST('t' AS BOOLEAN)))) THEN ('Excluded') WHEN (((gpp.ControlSchemeRisk = 'High') OR (gpp.SHMUPFlag = CAST('t' AS BOOLEAN)) OR (gpp.SoulslikeFlag = CAST('t' AS BOOLEAN)))) THEN (CASE  WHEN ((gpp.MitigationAvailable = CAST('t' AS BOOLEAN))) THEN ('Playable With Mitigation') ELSE 'High Risk' END) WHEN ((gpp.ControlSchemeRisk = 'Moderate')) THEN (CASE  WHEN ((gpp.MitigationAvailable = CAST('t' AS BOOLEAN))) THEN ('Playable With Mitigation') ELSE 'Moderate Risk' END) ELSE 'Playable' END AS playability_status FROM DimGame AS dg LEFT JOIN GamePlayabilityProfile AS gpp ON ((gpp.GameID = dg.GameID)) , rule_weights AS rw;
